internal.body:
      if (mode <= 0 || mode > MAX_MODE) {
        throw new fr.sorbonne_u.exceptions.PreconditionException("mode > 0 && mode <= MAX_MODE");
	  }
      double maxPowerLevel = fan.getMaxPowerLevelJava4();
      return (mode - 1) * maxPowerLevel/(MAX_MODE - 1);

      if (newPowerLevel < 0.0) {
		throw new fr.sorbonne_u.exceptions.PreconditionException("newPowerLevel >= 0.0");
	  }
      double maxPowerLevel = fan.getMaxPowerLevelJava4();
      if (newPowerLevel > maxPowerLevel) {
		newPowerLevel = maxPowerLevel;
	  }
      fan.setCurrentPowerLevelJava4(newPowerLevel);

      if (newMode <= 0 || newMode > MAX_MODE) {
        throw new fr.sorbonne_u.exceptions.PreconditionException("newMode > 0 && newMode <= MAX_MODE");
	  }
      double newPowerLevel = computePowerLevel(newMode);
      setPowerLevel(newPowerLevel);

upMode.body:
try {
  computeAndSetNewPowerLevel(currentMode + 1);
  currentMode++;
} catch(Exception e) {
  return false;
}
return true;

downMode.body:
try {
  computeAndSetNewPowerLevel(currentMode - 1);
  currentMode--;
} catch(Exception e) {
  return false;
}
return true;

setMode.body:
try {
  computeAndSetNewPowerLevel(modeIndex);
  currentMode = modeIndex;
} catch(Exception e) {
  return false;
}
return true;

suspend.body:
try {
  fan.setCurrentPowerLevelJava4(0.0);
  isSuspended = true;
} catch(Exception e) {
  return false;
}
return true;

resume.body:
try {
  computeAndSetNewPowerLevel(currentMode);
  isSuspended = false;
} catch(Exception e) {
  return false;
}
return true;

emergency.body:
double currentPower = fan.getCurrentPowerLevelJava4();
double maxPower = fan.getMaxPowerLevelJava4();
double ratio = currentPower / maxPower;
double ret = -1.0;
if (ratio >= 1.0) {
  ret = 1.0;
} else {
  ret = ratio;
}
return ret;
